extends "res://htd/htd_test.gd"


func _run_tests() -> void:
	var basket_scene := await instantiate_scene("res://basket.tscn")
	if not check("basket_scene", basket_scene != null, "La scena basket.tscn deve potersi istanziare senza errori"):
		return
	var star_scene := await instantiate_scene("res://star.tscn")
	if not check("star_scene", star_scene != null, "La scena star.tscn deve potersi istanziare senza errori"):
		return

	check("has_move_basket", has_function(basket_scene, "move_basket"), "basket.gd deve definire la funzione move_basket(delta)")
	check("has_reset_star", has_function(star_scene, "reset_star"), "star.gd deve definire la funzione reset_star()")
	check("has_is_caught", has_function(star_scene, "is_caught"), "star.gd deve definire la funzione is_caught(basket_position)")

	if has_function(star_scene, "reset_star"):
		star_scene.position = Vector2(999.0, 999.0)
		star_scene.set("is_collected", true)
		star_scene.call("reset_star")
		var pos_ok: bool = star_scene.position == Vector2(576, 80)
		var collected_ok: bool = star_scene.get("is_collected") == false
		check("reset_star_effect", pos_ok and collected_ok, "reset_star() deve riposizionare la stella a Vector2(576, 80) e impostare is_collected a false")

	if has_function(star_scene, "is_caught"):
		star_scene.position = Vector2(576, 600)
		var caught_near = star_scene.call("is_caught", Vector2(576, 600))
		var caught_far = star_scene.call("is_caught", Vector2(100, 100))
		check("is_caught_true", caught_near == true, "is_caught() deve restituire true quando il cesto è vicino alle coordinate della stella")
		check("is_caught_false", caught_far == false, "is_caught() deve restituire false quando il cesto è lontano dalla stella")

	var basket_start_x: float = basket_scene.position.x
	await hold_action("move_right", 15)
	check("basket_moves", basket_scene.position.x > basket_start_x, "Il cesto deve continuare a muoversi verso destra quando si preme move_right")
